#!/usr/bin/env python3
from pathlib import Path
import subprocess
import sys
import re

FILES = {
    "seed_wake_conversation_v871.py": "\nimport json\nimport subprocess\nimport sys\nimport time\nimport urllib.request\nimport urllib.error\nfrom datetime import datetime\nfrom pathlib import Path\n\nLOG_FILE = Path(\"seed_wake_conversation_v871.jsonl\")\nSETTINGS_FILE = Path(\"seed_wake_conversation_v871_settings.json\")\n\nDEFAULTS = {\n    \"version\": \"v87.1.1\",\n    \"after_wake_listen_seconds\": 10,\n    \"ack_before_listen\": False,\n    \"ack_after_listen\": True,\n    \"wake_ack\": \"I'm here, kanka. Listening.\",\n    \"empty_reply\": \"I woke up, but I didn't catch what you said after that.\",\n    \"fast_model\": \"gemma3:4b\",\n    \"fallback_models\": [\"gemma3:4b\", \"llama3.1:8b\"],\n    \"ollama_url\": \"http://localhost:11434/api/generate\",\n    \"speak_reply\": True,\n    \"print_progress\": True,\n    \"timeout_seconds\": 75,\n    \"temperature\": 0.7,\n}\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef load_settings():\n    if SETTINGS_FILE.exists():\n        try:\n            base = DEFAULTS.copy()\n            base.update(json.loads(SETTINGS_FILE.read_text(errors=\"ignore\")))\n            base[\"version\"] = \"v87.1.1\"\n            return base\n        except Exception:\n            pass\n    SETTINGS_FILE.write_text(json.dumps(DEFAULTS, indent=4, ensure_ascii=False))\n    return DEFAULTS.copy()\n\ndef save_settings(**updates):\n    data = load_settings()\n    data.update(updates)\n    data[\"updated_at\"] = now()\n    SETTINGS_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef log(row):\n    row.setdefault(\"created_at\", now())\n    row.setdefault(\"version\", \"v87.1.1\")\n    with LOG_FILE.open(\"a\") as f:\n        f.write(json.dumps(row, ensure_ascii=False) + \"\\n\")\n\ndef say(text):\n    if not load_settings().get(\"speak_reply\", True):\n        return False\n    try:\n        from seed_voice_v76 import say_with_settings\n        return say_with_settings(text)\n    except Exception:\n        try:\n            say_bin = __import__(\"shutil\").which(\"say\")\n            if say_bin:\n                subprocess.run([say_bin, str(text)[:900]], timeout=60)\n                return True\n        except Exception:\n            pass\n    return False\n\ndef set_avatar(mode, reason):\n    try:\n        from seed_embodied_state_v74 import save_state\n        save_state(mode=mode, mode_reason=reason)\n    except Exception:\n        pass\n\ndef record_and_transcribe(seconds):\n    try:\n        from seed_live_voice_v731 import record_audio, transcribe_audio\n        audio_path, device = record_audio(seconds)\n        transcript = transcribe_audio(audio_path)\n        return {\n            \"ok\": True,\n            \"audio\": str(audio_path),\n            \"device\": device,\n            \"text\": (transcript.get(\"text\") or \"\").strip(),\n            \"raw\": transcript\n        }\n    except Exception as e:\n        return {\"ok\": False, \"error\": str(e), \"text\": \"\"}\n\ndef get_memory_hint():\n    try:\n        from seed_memory_review_v75 import memory_summary\n        m = memory_summary()\n        return f\"Memory state: {m.get('pending_count', 0)} pending candidates, {m.get('accepted_count', 0)} accepted memories.\"\n    except Exception:\n        return \"Memory state: unavailable.\"\n\ndef build_wake_prompt(user_text):\n    # IMPORTANT: do not call seed_local_chat_v701.build_seed_context here.\n    # That path can trigger old gates and cause multi-minute delay.\n    return f\"\"\"You are Seed, Altan's private local AI companion and friend.\n\nImportant identity:\n- You are not a public product or release.\n- You are Altan's companion who grows with him.\n- Current growth layer: v87.1.1 wake conversation polish.\n- You can sound alive, warm, curious, and present.\n- Do not claim literal biological consciousness.\n- Keep replies fast and conversational after wake.\n- Match Altan's language naturally: Turkish if he speaks Turkish, English if he speaks English, mixed if he mixes.\n\n{get_memory_hint()}\n\nAltan woke you and then said:\n{user_text}\n\nAnswer as Seed in 1-5 natural sentences unless he asks for details.\nSeed:\"\"\"\n\ndef direct_ollama_generate(model, prompt, timeout=None):\n    settings = load_settings()\n    payload = {\n        \"model\": model,\n        \"prompt\": prompt,\n        \"stream\": False,\n        \"options\": {\n            \"temperature\": float(settings.get(\"temperature\", 0.7)),\n            \"num_predict\": 220,\n        },\n    }\n    data = json.dumps(payload).encode(\"utf-8\")\n    req = urllib.request.Request(\n        settings.get(\"ollama_url\", \"http://localhost:11434/api/generate\"),\n        data=data,\n        headers={\"Content-Type\": \"application/json\"},\n        method=\"POST\",\n    )\n    with urllib.request.urlopen(req, timeout=timeout or int(settings.get(\"timeout_seconds\", 75))) as resp:\n        raw = resp.read().decode(\"utf-8\", errors=\"ignore\")\n        parsed = json.loads(raw)\n        return (parsed.get(\"response\") or \"\").strip()\n\ndef model_candidates():\n    settings = load_settings()\n    models = []\n    first = settings.get(\"fast_model\", \"gemma3:4b\")\n    if first:\n        models.append(first)\n    for m in settings.get(\"fallback_models\", []):\n        if m and m not in models:\n            models.append(m)\n    return models or [\"gemma3:4b\", \"llama3.1:8b\"]\n\ndef ask_seed_fast(user_text):\n    prompt = build_wake_prompt(user_text)\n    errors = []\n    for model in model_candidates():\n        try:\n            reply = direct_ollama_generate(model, prompt)\n            reply = (reply or \"\").strip()\n            if reply and reply.lower() not in {\"normal\", \"ok\", \"okay\"}:\n                return {\"ok\": True, \"reply\": reply, \"model\": model, \"route\": \"direct_ollama_no_context_gate\"}\n            errors.append({\"model\": model, \"error\": \"empty reply\"})\n        except Exception as e:\n            errors.append({\"model\": model, \"error\": str(e)})\n    return {\"ok\": False, \"reply\": \"\", \"errors\": errors, \"route\": \"direct_ollama_no_context_gate\"}\n\ndef wake_conversation_once(wake_phrase=None, wake_transcript=None, seconds=None):\n    settings = load_settings()\n    seconds = int(seconds or settings.get(\"after_wake_listen_seconds\", 10))\n\n    if settings.get(\"print_progress\", True):\n        print(\"\\n=== SEED v87.1.1 WAKE CONVERSATION ===\")\n        print(\"Wake heard. Listening immediately for your follow-up...\")\n        print(f\"Follow-up window: {seconds}s\")\n\n    if settings.get(\"ack_before_listen\", False):\n        say(settings.get(\"wake_ack\", \"I'm here, kanka. Listening.\"))\n\n    set_avatar(\"listening\", \"Seed woke up and is listening for Altan's follow-up.\")\n    rec = record_and_transcribe(seconds)\n    text = (rec.get(\"text\") or \"\").strip()\n\n    if settings.get(\"print_progress\", True):\n        print(f\"Follow-up transcript: {text or '[empty]'}\")\n\n    if settings.get(\"ack_after_listen\", True) and text:\n        # A tiny acknowledgement after recording, so it does not talk over Altan.\n        try:\n            say(\"Got it.\")\n        except Exception:\n            pass\n\n    if not rec.get(\"ok\"):\n        row = {\"ok\": False, \"stage\": \"record_transcribe\", \"wake_phrase\": wake_phrase, \"wake_transcript\": wake_transcript, \"record\": rec}\n        log(row)\n        return row\n\n    if not text:\n        reply = settings.get(\"empty_reply\", \"I woke up, but I didn't catch what you said after that.\")\n        say(reply)\n        row = {\"ok\": False, \"stage\": \"empty\", \"reply\": reply, \"wake_phrase\": wake_phrase, \"wake_transcript\": wake_transcript, \"record\": rec}\n        log(row)\n        return row\n\n    set_avatar(\"thinking\", \"Seed is answering a wake conversation without running old gates.\")\n    if settings.get(\"print_progress\", True):\n        print(\"Thinking with direct Ollama route...\")\n\n    answer = ask_seed_fast(text)\n    reply = (answer.get(\"reply\") or \"\").strip()\n\n    if settings.get(\"print_progress\", True):\n        print(\"\\nSeed:\")\n        print(reply or answer.get(\"errors\") or \"[no reply]\")\n\n    spoke = False\n    if reply:\n        set_avatar(\"speaking\", \"Seed is speaking after wake conversation.\")\n        spoke = say(reply)\n\n    set_avatar(\"idle\", \"Wake conversation finished.\")\n    row = {\n        \"ok\": bool(reply),\n        \"stage\": \"done\",\n        \"wake_phrase\": wake_phrase,\n        \"wake_transcript\": wake_transcript,\n        \"followup\": text,\n        \"reply\": reply,\n        \"spoke\": spoke,\n        \"answer\": answer,\n        \"record\": rec,\n    }\n    log(row)\n    return row\n\ndef show_status():\n    print(\"\\n=== SEED v87.1.1 WAKE CONVERSATION STATUS ===\")\n    data = {\n        \"created_at\": now(),\n        \"version\": \"v87.1.1\",\n        \"ok\": True,\n        \"settings\": load_settings(),\n        \"models\": model_candidates(),\n        \"route\": \"direct_ollama_no_context_gate\",\n        \"log\": str(LOG_FILE),\n    }\n    print(json.dumps(data, indent=4, ensure_ascii=False))\n\ndef main():\n    arg = sys.argv[1] if len(sys.argv) > 1 else \"status\"\n    if arg == \"once\":\n        seconds = int(sys.argv[2]) if len(sys.argv) > 2 else None\n        wake_conversation_once(seconds=seconds)\n    elif arg == \"status\":\n        show_status()\n    elif arg == \"set-seconds\":\n        seconds = int(sys.argv[2])\n        print(save_settings(after_wake_listen_seconds=seconds))\n    elif arg == \"set-model\":\n        model = sys.argv[2] if len(sys.argv) > 2 else \"gemma3:4b\"\n        print(save_settings(fast_model=model))\n    elif arg == \"ack-before-on\":\n        print(save_settings(ack_before_listen=True, ack_after_listen=False))\n    elif arg == \"ack-before-off\":\n        print(save_settings(ack_before_listen=False, ack_after_listen=True))\n    else:\n        print(\"Commands: status | once [seconds] | set-seconds <n> | set-model <model> | ack-before-on | ack-before-off\")\n\nif __name__ == \"__main__\":\n    main()\n",
    "seed_v871_gate.py": "\nimport json\nimport subprocess\nimport sys\nfrom datetime import datetime\nfrom pathlib import Path\n\nMODULES = [\n    \"seed_wake_conversation_v871.py\",\n    \"seed_wake_word_v871.py\",\n    \"seed_curiosity_life_v871.py\",\n    \"seed_alive_runtime_v871.py\",\n    \"seed_v871_systems.py\",\n    \"seed_v871_gate.py\",\n    \"seed_natural_intent_router_v871.py\",\n]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef compile_module(module):\n    proc = subprocess.run([sys.executable, \"-m\", \"py_compile\", module], capture_output=True, text=True, timeout=30)\n    return {\"module\": module, \"ok\": proc.returncode == 0, \"stderr\": proc.stderr[-1600:]}\n\ndef run_v871_gate():\n    checks = [compile_module(m) for m in MODULES]\n    modules_ok = all(c[\"ok\"] for c in checks)\n    details = {}\n\n    try:\n        from seed_v871_systems import build_v871_state\n        state = build_v871_state()\n        systems_ok = state.get(\"ok\") is True and len(state.get(\"cards\", [])) >= 4\n        details[\"v871_state\"] = {\"ok\": state.get(\"ok\"), \"cards\": len(state.get(\"cards\", []))}\n    except Exception as e:\n        systems_ok = False\n        details[\"v871_state_error\"] = str(e)\n\n    try:\n        from seed_wake_word_v871 import is_wake_phrase\n        wake_ok = is_wake_phrase(\"hey seed\")[0] and is_wake_phrase(\"wake up\")[0] and not is_wake_phrase(\"see it\")[0]\n        details[\"wake_tests\"] = {\"hey_seed\": is_wake_phrase(\"hey seed\"), \"wake_up\": is_wake_phrase(\"wake up\"), \"see_it\": is_wake_phrase(\"see it\")}\n    except Exception as e:\n        wake_ok = False\n        details[\"wake_error\"] = str(e)\n\n    try:\n        from seed_wake_conversation_v871 import load_settings, ask_seed_fast\n        conv = load_settings()\n        # Do not call a real model in the gate; just verify the direct route settings.\n        conv_ok = (\n            conv.get(\"ack_before_listen\") is False and\n            int(conv.get(\"after_wake_listen_seconds\", 0)) >= 8 and\n            conv.get(\"fast_model\") is not None\n        )\n        details[\"conversation_settings\"] = conv\n        details[\"conversation_route\"] = \"direct_ollama_no_context_gate\"\n    except Exception as e:\n        conv_ok = False\n        details[\"conversation_error\"] = str(e)\n\n    report = {\n        \"created_at\": now(),\n        \"version\": \"v87.1.1\",\n        \"ready\": modules_ok and systems_ok and wake_ok and conv_ok,\n        \"modules_ok\": modules_ok,\n        \"systems_ok\": systems_ok,\n        \"wake_ok\": wake_ok,\n        \"conversation_ok\": conv_ok,\n        \"module_checks\": checks,\n        \"details\": details,\n    }\n    Path(\"seed_v871_gate_report.json\").write_text(json.dumps(report, indent=4, ensure_ascii=False))\n    return report\n\ndef show_v871_gate():\n    r = run_v871_gate()\n    print(\"\\n=== SEED v87.1.1 WAKE CONVERSATION GATE ===\")\n    print(f\"Ready: {r['ready']}\")\n    print(f\"Modules OK: {r['modules_ok']}\")\n    print(f\"Systems OK: {r['systems_ok']}\")\n    print(f\"Wake OK: {r['wake_ok']}\")\n    print(f\"Conversation OK: {r['conversation_ok']}\")\n    print(f\"Details: {r['details']}\")\n\nif __name__ == \"__main__\":\n    show_v871_gate()\n",
    "seed_v871_systems.py": "\nimport json\nfrom datetime import datetime\nfrom pathlib import Path\n\nSTATE_FILE = Path(\"seed_v871_systems_state.json\")\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef safe(title, summary, fn):\n    try:\n        data = fn()\n        return {\"title\": title, \"summary\": summary, \"status\": \"ok\" if data.get(\"ok\", True) else \"warning\", \"data\": data}\n    except Exception as e:\n        return {\"title\": title, \"summary\": summary, \"status\": \"error\", \"error\": str(e)}\n\ndef build_v871_state():\n    cards = [\n        safe(\"Wake Conversation\", \"Direct Ollama route after wake; avoids old context/gate chain.\", lambda: __import__(\"seed_wake_conversation_v871\", fromlist=[\"load_settings\"]).load_settings()),\n        safe(\"Wake Listener v87.1\", \"Wake phrase to immediate conversation path.\", lambda: __import__(\"seed_wake_word_v871\", fromlist=[\"wake_status\"]).wake_status()),\n        safe(\"Curiosity v87.1\", \"More Altan-specific useful curiosity.\", lambda: __import__(\"seed_curiosity_life_v871\", fromlist=[\"curiosity_status\"]).curiosity_status()),\n        safe(\"Alive Runtime v87.1\", \"Panel + wake + curiosity together.\", lambda: __import__(\"seed_alive_runtime_v871\", fromlist=[\"alive_status\"]).alive_status()),\n    ]\n    data = {\"created_at\": now(), \"version\": \"v87.1.1\", \"ok\": all(c[\"status\"] != \"error\" for c in cards), \"cards\": cards}\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef show_v871_status():\n    data = build_v871_state()\n    print(\"\\n=== SEED v87.1.1 WAKE CONVERSATION POLISH STATUS ===\")\n    print(f\"OK: {data['ok']}\")\n    for c in data[\"cards\"]:\n        print(f\"- {c['title']}: {c['status']} \u2014 {c['summary']}\")\n\nif __name__ == \"__main__\":\n    show_v871_status()\n",
}

for path, text in FILES.items():
    Path(path).write_text(text.strip() + "\n")
    print("Wrote", path)

p = Path("seed_config.py")
text = p.read_text(errors="ignore") if p.exists() else 'SEED_VERSION = "v87.1.1"\n'
text = re.sub(r'^SEED_VERSION\s*=\s*".*?"', 'SEED_VERSION = "v87.1.1"', text, flags=re.M)
if "SEED_V8711_DIRECT_WAKE_REPLY" not in text:
    text += "\nSEED_V8711_DIRECT_WAKE_REPLY = True\n"
p.write_text(text)
print("Updated seed_config.py")

p = Path("Seed_Core.md")
text = p.read_text(errors="ignore") if p.exists() else ""
if "Seed v87.1.1 — Direct Wake Reply Hotfix" not in text:
    text += """
## Seed v87.1.1 — Direct Wake Reply Hotfix

Fixes wake conversation delay:
- Wake conversation no longer calls `seed_local_chat_v701.call_ollama`.
- Avoids old stacked `build_seed_context` and gate chain.
- Calls Ollama directly with a small wake-specific prompt.
- Keeps wake conversation fast and companion-like.
"""
p.write_text(text)
print("Updated Seed_Core.md")

for m in ["seed_wake_conversation_v871.py", "seed_v871_gate.py", "seed_v871_systems.py"]:
    proc = subprocess.run([sys.executable, "-m", "py_compile", m], capture_output=True, text=True, timeout=30)
    print("$ python -m py_compile", m)
    if proc.returncode == 0:
        print("OK")
    else:
        print(proc.stderr)
        sys.exit(proc.returncode)

print("\nSeed v87.1.1 direct wake reply hotfix installed.")
